mapper.select:
SELECT s.print_no AS printNo, s.status, s.copies, s.printed_at AS printedAt, s.void_reason AS voidReason, s.record_id AS recordId, COALESCE(p.create_time, r.create_time) AS prescriptionTime, c.client_name AS clientName, pt.pet_name AS petName, d.doctor_name AS doctorName, d.doctor_cert AS doctorCert FROM rx_print_supplement s LEFT JOIN prescription p ON s.prescription_id = p.prescription_id LEFT JOIN medical_record r ON s.record_id = r.record_id LEFT JOIN client c ON r.client_id = c.client_id LEFT JOIN pet pt ON r.pet_id = pt.pet_id LEFT JOIN doctor d ON r.doctor_id = d.doctor_id
AND COALESCE(p.create_time, r.create_time) >= #{startDate}
AND COALESCE(p.create_time, r.create_time) < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
AND r.doctor_id = #{doctorId}
AND (c.client_name LIKE #{kw} OR pt.pet_name LIKE #{kw} OR s.print_no LIKE #{kw})
AND s.printed_at IS NOT NULL
AND s.printed_at IS NULL
AND s.status = #{status}
ORDER BY s.printed_at DESC
